earlier = load('earlier-projects.json')
for p in earlier:
    gallery = ''.join(f'<figure><a href="../assets/images/{e(src)}" target="_blank" rel="noopener"><img src="../assets/images/{e(src)}" alt="{e(alt)}" width="450" height="975" loading="lazy"></a><figcaption>{e(alt)}</figcaption></figure>' for src,alt in p['images'])
