    boundary = t('Original Flutter delivery; later product changes belong to another team. These images are the supplied portfolio materials.','تطوير نسخة Flutter الأصلية؛ التحديثات اللاحقة نفذها فريق آخر. الصور من ملفات البورتفوليو المرفقة.','p','archive-note') if p['id']=='overdeal' else ''
